import{_ as t,o,c as a,a3 as r}from"./chunks/framework.DACwFHq9.js";const h=JSON.parse('{"title":"Enterprise MCP Tools & Prompts Reference","description":"Reference documentation for Notely Model Context Protocol (MCP) server capabilities, 7 enterprise unified tools, MCP prompts, and dual-transport integration.","frontmatter":{"title":"Enterprise MCP Tools & Prompts Reference","description":"Reference documentation for Notely Model Context Protocol (MCP) server capabilities, 7 enterprise unified tools, MCP prompts, and dual-transport integration.","keywords":"MCP, Model Context Protocol, SSE, Streamable HTTP, AI, Claude Desktop, Cursor, prompts, enterprise tools","category":"Developer"},"headers":[],"relativePath":"mcp-tools-reference.md","filePath":"mcp-tools-reference.md","lastUpdated":1789664586000}'),i={name:"mcp-tools-reference.md"};function n(s,e,d,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="notely-enterprise-mcp-tools-prompts-reference" tabindex="-1">Notely Enterprise MCP Tools &amp; Prompts Reference <a class="header-anchor" href="#notely-enterprise-mcp-tools-prompts-reference" aria-label="Permalink to &quot;Notely Enterprise MCP Tools &amp; Prompts Reference&quot;">​</a></h1><p>Notely embeds a high-performance <strong>dual-transport Model Context Protocol (MCP)</strong> server (Streamable HTTP &amp; SSE) enabling external AI clients (such as Google Antigravity, Claude Desktop, Cursor, IDE agents, and LLMs) to query, search, analyze, and manipulate workspace content safely and self-sufficiently without handholding.</p><hr><h2 id="_1-architecture-highlights" tabindex="-1">1. Architecture Highlights <a class="header-anchor" href="#_1-architecture-highlights" aria-label="Permalink to &quot;1. Architecture Highlights&quot;">​</a></h2><ul><li><strong>Dual Transport</strong>: Supports Streamable HTTP (<code>http://127.0.0.1:3700/mcp</code>) and SSE (<code>http://127.0.0.1:3700/sse</code> with <code>/messages</code>).</li><li><strong>Standard MCP Prompts</strong>: Exposes MCP Prompts primitive (<code>prompts/list</code>, <code>prompts/get</code>, HTTP <code>GET /prompts</code>) for interactive workflows.</li><li><strong>Enterprise Design</strong>: Merged fragmented micro-tools into <strong>7 self-sufficient, high-signal tools</strong>. Every tool returns rich structured context (match breakdowns, cleansing, frontmatter, backlinks, git history).</li><li><strong>Safety &amp; Permissions</strong>: Granular write protection toggle (<code>allowWriteTools</code>). All write tools require explicit permission. Dry-run mode (<code>dryRun: true</code>) supported on destructive operations.</li><li><strong>Fuzzy Recovery</strong>: Smart path resolution with Levenshtein-based <code>didYouMean</code> suggestions on missing files.</li><li><strong>Atomic File I/O</strong>: Temporary file staging with rename to prevent partial writes or corruption.</li></ul><hr><h2 id="_2-the-7-unified-enterprise-tools" tabindex="-1">2. The 7 Unified Enterprise Tools <a class="header-anchor" href="#_2-the-7-unified-enterprise-tools" aria-label="Permalink to &quot;2. The 7 Unified Enterprise Tools&quot;">​</a></h2><h3 id="search-read-only" tabindex="-1"><code>search</code> <em>(Read-Only)</em> <a class="header-anchor" href="#search-read-only" aria-label="Permalink to &quot;`search` *(Read-Only)*&quot;">​</a></h3><p>Multi-modal search engine for Notely notes &amp; workspace. Supports fulltext keyword matching, regex, YAML frontmatter tags, author, and semantic graph. Optionally queries the web when source is &quot;web&quot; or &quot;all&quot;. Returns scored hits with match breakdown.</p><p><strong>Parameters:</strong></p><ul><li><code>query</code> (<code>string</code>): Search keyword, phrase, or regex pattern. Examples: &quot;system architecture&quot;, &quot;TODO&quot;, &quot;/#v\\d+/&quot;</li><li><code>source</code> (<code>string</code>): Where to search: &quot;notes&quot; (workspace notes), &quot;web&quot; (external web search), or &quot;all&quot; (both)</li><li><code>mode</code> (<code>string</code>): Search strategy. &quot;auto&quot; intelligently detects regex, tags, and semantic intent</li><li><code>tags</code> (<code>array</code>): Filter notes matching specific tags (e.g. [&quot;architecture&quot;, &quot;draft&quot;])</li><li><code>author</code> (<code>string</code>): Filter notes by author or creator from YAML frontmatter</li><li><code>folder</code> (<code>string</code>): Limit search scope to a subfolder within the workspace</li><li><code>limit</code> (<code>number</code>): Maximum number of results to return (default: 20, max: 50)</li></ul><h3 id="read-note-read-only" tabindex="-1"><code>read_note</code> <em>(Read-Only)</em> <a class="header-anchor" href="#read-note-read-only" aria-label="Permalink to &quot;`read_note` *(Read-Only)*&quot;">​</a></h3><p>Comprehensive 360° note inspector. Retrieves complete note context in ONE call: raw markdown, cleansed plain text, heading outline, frontmatter metadata, inline tags, embedded media assets (with disk existence), Mermaid/Excalidraw diagrams, checklist tasks, outgoing links, backlinks from other notes, and recent git commit history.</p><p><strong>Parameters:</strong></p><ul><li><code>pathOrTitle</code> (<code>string</code>, required): Note path (e.g. &quot;docs/Architecture.md&quot;), filename (&quot;Architecture.md&quot;), or note title / wikilink (&quot;[[Architecture]]&quot;). Auto-resolves case-insensitively and fuzzy matches if misspelled.</li><li><code>include</code> (<code>object</code>): Optional toggles to omit unneeded sections. Defaults to all true.</li><li><code>startLine</code> (<code>number</code>): Starting line number for pagination (default: 1)</li><li><code>maxLines</code> (<code>number</code>): Maximum lines to return per call to prevent context blowout (default: 400)</li></ul><h3 id="edit-note-w" tabindex="-1"><code>edit_note</code> <strong>[W]</strong> <a class="header-anchor" href="#edit-note-w" aria-label="Permalink to &quot;`edit_note` **[W]**&quot;">​</a></h3><p>Unified, atomic note authoring and editing engine. Supports creating new notes, replacing content, appending, prepending, line-range patching, heading-anchored insertion, frontmatter metadata merging, note renaming, and safe deletion. All operations use atomic disk staging to prevent file corruption.</p><p><strong>Parameters:</strong></p><ul><li><code>filePath</code> (<code>string</code>, required): Target note path (e.g. &quot;docs/Roadmap.md&quot; or &quot;NewNote.md&quot;)</li><li><code>operation</code> (<code>string</code>, required): Operation to perform: &quot;create&quot; (new note), &quot;replace&quot; (full content), &quot;append&quot; (add to bottom), &quot;prepend&quot; (add to top), &quot;patch&quot; (targeted search/replace or line edit), &quot;insert_at&quot; (insert at line or heading), &quot;update_frontmatter&quot; (merge metadata), &quot;set_title&quot; (update H1 and meta), &quot;rename&quot; (move/rename), &quot;delete&quot; (remove)</li><li><code>content</code> (<code>string</code>): Text content to write, append, prepend, or insert</li><li><code>frontmatter</code> (<code>object</code>): Key-value pairs to set or merge in YAML frontmatter</li><li><code>patch</code> (<code>object</code>): Parameters for &quot;patch&quot; operation: search and replace strings, or line numbers</li><li><code>targetHeading</code> (<code>string</code>): Heading text for &quot;insert_at&quot; operation (e.g. &quot;## Next Steps&quot;)</li><li><code>newPath</code> (<code>string</code>): New path or filename when using &quot;rename&quot; operation</li><li><code>dryRun</code> (<code>boolean</code>): If true, computes and returns the diff without making changes on disk</li></ul><h3 id="manage-tasks-w" tabindex="-1"><code>manage_tasks</code> <strong>[W]</strong> <a class="header-anchor" href="#manage-tasks-w" aria-label="Permalink to &quot;`manage_tasks` **[W]**&quot;">​</a></h3><p>Workspace-wide and note-level checklist &amp; task manager. Finds, creates, toggles, moves, or archives tasks (- [ ], - [x]). Can filter by status (open, completed, in-progress) and due dates (today, overdue).</p><p><strong>Parameters:</strong></p><ul><li><code>operation</code> (<code>string</code>, required): &quot;list&quot; (scan and return tasks), &quot;create&quot; (add new task), &quot;toggle&quot; (switch [ ] &lt;-&gt; [x]), &quot;complete&quot; (mark [x]), &quot;move&quot; (relocate task to another note), &quot;archive_completed&quot; (move all [x] tasks to bottom section)</li><li><code>notePath</code> (<code>string</code>): Specific note file path. Omit for &quot;list&quot; to scan entire workspace.</li><li><code>status</code> (<code>string</code>): Filter tasks by status</li><li><code>filter</code> (<code>string</code>): Filter tasks by due date: &quot;today&quot; (due today), &quot;overdue&quot; (past due date)</li><li><code>taskText</code> (<code>string</code>): Text of the task to create, complete, or move</li><li><code>line</code> (<code>number</code>): Specific line number of the task in the note</li><li><code>targetNotePath</code> (<code>string</code>): Destination note path when using &quot;move&quot; operation</li><li><code>dueDate</code> (<code>string</code>): Optional due date in YYYY-MM-DD format for created task</li></ul><h3 id="manage-diagrams-w" tabindex="-1"><code>manage_diagrams</code> <strong>[W]</strong> <a class="header-anchor" href="#manage-diagrams-w" aria-label="Permalink to &quot;`manage_diagrams` **[W]**&quot;">​</a></h3><p>Unified visual diagram and whiteboard manager. Reads, creates, and updates Mermaid diagrams inside markdown notes, as well as standalone .excalidraw JSON and Draw.io XML drawing files.</p><p><strong>Parameters:</strong></p><ul><li><code>operation</code> (<code>string</code>, required): &quot;list&quot; (catalog all diagrams), &quot;read&quot; (fetch diagram code/elements), &quot;create&quot; (insert or create drawing), &quot;update&quot; (modify diagram), &quot;delete&quot; (remove diagram)</li><li><code>notePath</code> (<code>string</code>): Path of markdown note containing embedded Mermaid diagram</li><li><code>filePath</code> (<code>string</code>): Path of standalone .excalidraw or .drawio diagram file</li><li><code>diagramIndex</code> (<code>number</code>): Zero-based index of Mermaid diagram if note contains multiple diagrams</li><li><code>type</code> (<code>string</code>): Diagram format</li><li><code>content</code> (<code>string</code>): Mermaid code string or Excalidraw/Drawio JSON/XML content</li></ul><h3 id="workspace-overview-read-only" tabindex="-1"><code>workspace_overview</code> <em>(Read-Only)</em> <a class="header-anchor" href="#workspace-overview-read-only" aria-label="Permalink to &quot;`workspace_overview` *(Read-Only)*&quot;">​</a></h3><p>Workspace intelligence, structure, health, and diagnostics. Returns hierarchical folder trees, knowledge graph relationships, disk storage stats, link integrity audits (broken wikilinks), and recent file activity.</p><p><strong>Parameters:</strong></p><ul><li><code>operation</code> (<code>string</code>, required): &quot;summary&quot; (health &amp; note count), &quot;tree&quot; (folder/file hierarchy), &quot;graph&quot; (wikilink nodes &amp; edges), &quot;lint&quot; (audit broken wikilinks &amp; empty notes), &quot;index&quot; (structured notes catalog), &quot;recent_activity&quot; (recent modified notes)</li><li><code>folder</code> (<code>string</code>): Scoped directory for tree, index, or lint operations</li><li><code>maxDepth</code> (<code>number</code>): Maximum folder depth for tree hierarchy (default: 4)</li></ul><h3 id="git-control-w" tabindex="-1"><code>git_control</code> <strong>[W]</strong> <a class="header-anchor" href="#git-control-w" aria-label="Permalink to &quot;`git_control` **[W]**&quot;">​</a></h3><p>Workspace Git version control engine. Inspect status, view diffs, view commit logs, commit changes, branch, pull, push, stash, or revert changes within the workspace repository.</p><p><strong>Parameters:</strong></p><ul><li><code>action</code> (<code>string</code>, required): Git operation to perform</li><li><code>message</code> (<code>string</code>): Commit message for &quot;commit&quot; action</li><li><code>branchName</code> (<code>string</code>): Branch name for &quot;branch&quot; or &quot;checkout&quot; actions</li><li><code>path</code> (<code>string</code>): File path to scope diff or log operations</li><li><code>commitHash</code> (<code>string</code>): Commit hash for &quot;revert&quot; action</li><li><code>limit</code> (<code>number</code>): Number of commits to return for &quot;log&quot; action</li></ul><hr><h2 id="_3-standard-mcp-prompts-reference-5-prompts" tabindex="-1">3. Standard MCP Prompts Reference (5 Prompts) <a class="header-anchor" href="#_3-standard-mcp-prompts-reference-5-prompts" aria-label="Permalink to &quot;3. Standard MCP Prompts Reference (5 Prompts)&quot;">​</a></h2><p>Notely registers 5 standard MCP prompt templates discoverable via <code>prompts/list</code> and executable via <code>prompts/get</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Prompt Name</th><th style="text-align:left;">Arguments</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>summarize_note</code></td><td style="text-align:left;"><code>notePath (req), depth</code></td><td style="text-align:left;">Generate an executive summary, key takeaways, and action items for a workspace note.</td></tr><tr><td style="text-align:left;"><code>plan_tasks</code></td><td style="text-align:left;"><code>goal (req), targetNote, includeDates</code></td><td style="text-align:left;">Break down a project goal or feature into actionable checklist tasks and append them to a note.</td></tr><tr><td style="text-align:left;"><code>explore_knowledge_graph</code></td><td style="text-align:left;"><code>topicOrNote (req), maxDepth</code></td><td style="text-align:left;">Analyze relationships, backlinks, and conceptual clusters around a topic or note in the workspace.</td></tr><tr><td style="text-align:left;"><code>refactor_note</code></td><td style="text-align:left;"><code>notePath (req)</code></td><td style="text-align:left;">Clean up an unstructured note: format frontmatter, ensure clean H1-H3 hierarchy, and detect unlinked mentions.</td></tr><tr><td style="text-align:left;"><code>daily_review</code></td><td style="text-align:left;"><code>filter</code></td><td style="text-align:left;">Perform a daily briefing: inspect open/overdue tasks across the workspace and summarize recently edited notes.</td></tr></tbody></table><hr><h2 id="_4-claude-desktop-external-client-configuration" tabindex="-1">4. Claude Desktop &amp; External Client Configuration <a class="header-anchor" href="#_4-claude-desktop-external-client-configuration" aria-label="Permalink to &quot;4. Claude Desktop &amp; External Client Configuration&quot;">​</a></h2><p>Add Notely to your <code>claude_desktop_config.json</code>:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;notely&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:3700/mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer YOUR_OPTIONAL_TOKEN&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><hr><h2 id="_5-write-operations-permission-control" tabindex="-1">5. Write Operations Permission Control <a class="header-anchor" href="#_5-write-operations-permission-control" aria-label="Permalink to &quot;5. Write Operations Permission Control&quot;">​</a></h2><p>When write access is disabled (<code>allowWriteTools: false</code>), all tools marked <strong>[W]</strong> (<code>edit_note</code>, <code>manage_tasks</code>, <code>manage_diagrams</code>, <code>git_control</code>) are automatically filtered out from external discovery (<code>tools/list</code>) and blocked with a <code>WRITE_DISABLED</code> error envelope. Read-only query tools (<code>search</code>, <code>read_note</code>, <code>workspace_overview</code>) remain active and safe to call.</p>',46)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
